export const BUILD = '2026-10-07.5';
// A bounded best-effort isolate cache; Sites Workers cannot use caches.default.
const RECEIPT_CACHE = new Map();
export const NOTICE_AT = '2026-10-06T19:32:35.558Z';
export const NETWORKS = {
  mainnet: { id: 2741, label: 'Abstract mainnet', api: 'https://block-explorer-api.mainnet.abs.xyz', rpc: 'https://api.mainnet.abs.xyz', explorer: 'https://abscan.org', native: 'https://explorer.mainnet.abs.xyz' },
  testnet: { id: 11124, label: 'Abstract testnet', api: 'https://block-explorer-api.testnet.abs.xyz', rpc: 'https://api.testnet.abs.xyz', explorer: 'https://sepolia.abscan.org', native: 'https://explorer.testnet.abs.xyz' },
};
export function validAddress(value) {
  return typeof value === 'string' && /^0x[0-9a-f]{40}$/i.test(value) && !/^0x0{40}$/i.test(value);
}
export const PORTAL_SEARCH = 'https://backend.portal.abs.xyz/api/search/global';
export function normalizeUsername(value) {
  return typeof value === 'string' ? value.trim().replace(/^@/, '') : '';
}
export function validUsername(value) {
  const name = normalizeUsername(value);
  return name.length >= 3 && name.length <= 30 && !/^0x/i.test(name) && !/[\u0000-\u001f\u007f<>/@\\]/.test(name);
}
export async function resolveIdentity(value, fetcher = fetch, now = Date.now()) {
  const input = typeof value === 'string' ? value.trim() : '';
  if (validAddress(input)) return { kind: 'address', address: input, username: null };
  if (!validUsername(input)) return { error: 'Enter your AGW username (3–30 characters) or paste a valid, nonzero 0x wallet address.', code: 'invalid-input', status: 400 };
  const username = normalizeUsername(input), source = new URL(PORTAL_SEARCH);
  source.search = new URLSearchParams({ query: username });
  try {
    const response = await fetcher(source.toString(), { headers: { accept: 'application/json', 'user-agent': 'Abstract-Time-Receipt/1.0' }, signal: AbortSignal.timeout(10000), redirect: 'manual' });
    if (!response.ok) throw new Error('Portal search HTTP ' + response.status);
    const data = await response.json();
    if (!Array.isArray(data?.results?.users)) throw new Error('Invalid Portal search response');
    const exact = data.results.users.filter(user => typeof user?.name === 'string' && user.name.toLowerCase() === username.toLowerCase());
    if (!exact.length) return { error: 'No exact AGW username found. Check the spelling or paste your wallet address instead.', code: 'username-not-found', status: 404 };
    if (exact.some(user => !validAddress(user.address))) throw new Error('Invalid Portal wallet address');
    const matches = new Map(exact.map(user => [user.address.toLowerCase(), user]));
    if (matches.size !== 1) return { error: 'More than one wallet uses that name. Paste your wallet address to get the right receipt.', code: 'ambiguous-username', status: 409 };
    const match = matches.values().next().value;
    return { kind: 'username', address: match.address, username: match.name, provider: 'Abstract Portal public search', sourceUrl: source.toString(), resolvedAt: new Date(now).toISOString() };
  } catch (error) {
    console.warn('Portal username search unavailable:', error instanceof Error ? error.message.replace(source.toString(), PORTAL_SEARCH).slice(0, 180) : 'Unexpected provider response');
    return { error: 'AGW username search is temporarily unavailable. Paste your wallet address instead, or retry shortly.', code: 'username-unavailable', status: 503 };
  }
}
export function escapeXml(value) {
  return String(value).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&apos;' }[c]));
}
export function elapsed(first, until) {
  const start = Date.parse(first), end = Date.parse(until);
  if (!Number.isFinite(start) || !Number.isFinite(end)) throw new Error('Invalid receipt dates');
  if (start > end) return { days: 0, hours: 0, minutes: 0, totalHours: 0, afterEndpoint: true };
  const mins = Math.floor((end - start) / 60000);
  return { days: Math.floor(mins / 1440), hours: Math.floor(mins / 60) % 24, minutes: mins % 60, totalHours: Math.floor(mins / 60), afterEndpoint: false };
}
export function earliestRecord(networks) {
  return networks.filter(n => n.status === 'found' && n.first).map(n => n.first).sort((a, b) => Date.parse(a.timestamp) - Date.parse(b.timestamp))[0] || null;
}
export function parseTransaction(row, address, network, now) {
  const blockNumber = Number(row?.blockNumber), seconds = Number(row?.timeStamp);
  if (!/^0x[0-9a-f]{64}$/i.test(row?.hash || '') || !Number.isSafeInteger(blockNumber) || blockNumber < 0 || !Number.isSafeInteger(seconds) || seconds <= 0 || seconds * 1000 > now + 30000) throw new Error('Explorer returned an invalid transaction');
  if (row.from?.toLowerCase() !== address.toLowerCase() && row.to?.toLowerCase() !== address.toLowerCase()) throw new Error('Explorer returned a transaction for a different address');
  return { network, chainId: NETWORKS[network].id, address, hash: row.hash.toLowerCase(), blockNumber, timestamp: new Date(seconds * 1000).toISOString(), from: row.from, to: row.to, direction: row.from.toLowerCase() === address.toLowerCase() ? 'sent' : 'received', succeeded: String(row.isError) === '0', explorerUrl: NETWORKS[network].explorer + '/tx/' + row.hash, nativeExplorerUrl: NETWORKS[network].native + '/tx/' + row.hash };
}
async function getJson(url, init, fetcher) {
  const response = await fetcher(url, { ...init, signal: AbortSignal.timeout(14000) });
  if (!response.ok) throw new Error('Provider HTTP ' + response.status);
  return response.json();
}
export async function lookupNetwork(network, address, fetcher = fetch, now = Date.now()) {
  const config = NETWORKS[network], apiUrl = new URL(config.api + '/api');
  apiUrl.search = new URLSearchParams({ module: 'account', action: 'txlist', address, startblock: '0', endblock: '999999999', page: '1', offset: '3', sort: 'asc' });
  const base = { network, chainId: config.id, address, provider: 'Abstract native explorer', sourceUrl: apiUrl.toString(), checkedAt: new Date(now).toISOString() };
  try {
    const data = await getJson(apiUrl.toString(), { headers: { accept: 'application/json' } }, fetcher);
    if (Array.isArray(data.result) && data.result.length === 0 && (data.status === '1' || (data.status === '0' && /^no transactions found$/i.test(data.message || '')))) return { ...base, status: 'no-records', first: null };
    if (data.status !== '1' || !Array.isArray(data.result) || !data.result.length) throw new Error('Explorer did not return a valid history');
    const rows = data.result.map(row => parseTransaction(row, address, network, now));
    if (rows.some((row, i) => i > 0 && (row.blockNumber < rows[i - 1].blockNumber || Date.parse(row.timestamp) < Date.parse(rows[i - 1].timestamp)))) throw new Error('Explorer history is not ascending');
    const first = rows[0], blockTag = '0x' + first.blockNumber.toString(16);
    const batch = [{ jsonrpc: '2.0', id: 1, method: 'eth_chainId', params: [] }, { jsonrpc: '2.0', id: 2, method: 'eth_getTransactionReceipt', params: [first.hash] }, { jsonrpc: '2.0', id: 3, method: 'eth_getBlockByNumber', params: [blockTag, false] }];
    const rpc = await getJson(config.rpc, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(batch) }, fetcher);
    if (!Array.isArray(rpc) || rpc.some(r => r.error)) throw new Error('RPC verification failed');
    const byId = new Map(rpc.map(r => [r.id, r.result])), chain = byId.get(1), receipt = byId.get(2), block = byId.get(3);
    if (Number.parseInt(chain, 16) !== config.id || !receipt || !block || receipt.transactionHash?.toLowerCase() !== first.hash || Number.parseInt(receipt.blockNumber, 16) !== first.blockNumber || Number.parseInt(block.number, 16) !== first.blockNumber || receipt.blockHash?.toLowerCase() !== block.hash?.toLowerCase() || !block.transactions?.some(h => typeof h === 'string' && h.toLowerCase() === first.hash)) throw new Error('Explorer and RPC disagree on transaction inclusion');
    if (receipt.from?.toLowerCase() !== address.toLowerCase() && receipt.to?.toLowerCase() !== address.toLowerCase()) throw new Error('RPC transaction is unrelated to this address');
    if (Number.parseInt(block.timestamp, 16) * 1000 !== Date.parse(first.timestamp)) throw new Error('Explorer and RPC disagree on timestamp');
    first.succeeded = receipt.status === '0x1';
    first.verification = 'RPC block, transaction inclusion, and chain ID cross-checked';
    return { ...base, status: 'found', first };
  } catch { return { ...base, status: 'unavailable', first: null, message: 'The explorer or RPC could not verify this history. Retry later or inspect the explorer directly. No date has been guessed.' }; }
}
export async function handleLookup(request, fetcher = fetch, now = Date.now()) {
  const url = new URL(request.url), input = (url.searchParams.get('query') ?? url.searchParams.get('address') ?? '').trim(), includeTestnet = url.searchParams.get('testnet') === '1', suppliedTestnetAddress = url.searchParams.get('testnetAddress');
  if (includeTestnet && suppliedTestnetAddress !== null && !validAddress(suppliedTestnetAddress.trim())) return json({ error: 'Enter a valid, nonzero 0x testnet address with 40 hexadecimal characters.', code: 'invalid-testnet-address' }, 400);
  const identity = await resolveIdentity(input, fetcher, now);
  if (identity.error) return json({ error: identity.error, code: identity.code }, identity.status);
  const address = identity.address, testnetAddress = suppliedTestnetAddress?.trim() || address;
  const requests = [lookupNetwork('mainnet', address, fetcher, now)];
  if (includeTestnet) requests.push(lookupNetwork('testnet', testnetAddress, fetcher, now));
  const networks = await Promise.all(requests);
  return json({ schema: 'abstract-time-receipt/v1', build: BUILD, generatedAt: new Date(now).toISOString(), announcementAt: NOTICE_AT, address, identity, testnetIncluded: includeTestnet, testnetAddress: includeTestnet ? testnetAddress : null, differentTestnetAddress: includeTestnet && testnetAddress.toLowerCase() !== address.toLowerCase(), networks, earliest: earliestRecord(networks), partial: networks.some(n => n.status === 'unavailable'), methodology: 'Elapsed calendar time since the earliest indexed normal transaction involving a supplied address (sent or received). Includes failed included transactions. Not actual hours spent, wallet ownership, AGW identity, or an estimate of money lost. Internal calls and token transfers can predate this record. Separate testnet addresses are self-reported associations.' });
}
function json(data, status = 200) { return new Response(JSON.stringify(data), { status, headers: { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store', 'x-content-type-options': 'nosniff' } }); }

export const COMMUNITY_TOPICS = {trust:'Time & trust',xp:'XP & rewards',fees:'Fees',communication:'Communication',builders:'Builders',roadmap:'Quantum & roadmap'};
const DAY_MS = 86400000;
async function digest(value) { return [...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(value)))].map(v=>v.toString(16).padStart(2,'0')).join(''); }
function accessKey() { return [...crypto.getRandomValues(new Uint8Array(32))].map(v=>v.toString(16).padStart(2,'0')).join(''); }
function publicContribution(row,now) {
  return {id:row.id,address:row.address,firstAt:new Date(row.first_at).toISOString(),days:Math.max(0,Math.floor((now-row.first_at)/DAY_MS)),network:row.network,transactionUrl:NETWORKS[row.network].explorer+'/tx/'+row.tx_hash,partial:!!row.partial,message:row.message,topic:row.topic,createdAt:new Date(row.created_at).toISOString(),updatedAt:new Date(row.updated_at).toISOString()};
}
export async function handleCommunity(request,env,fetcher=fetch,now=Date.now()) {
  const url=new URL(request.url),db=env?.DB;
  if(!db)return json({error:'The community ledger is temporarily unavailable. Your receipt still works.'},503);
  const match=new RegExp('^/api/community/(' + UUID_PATTERN + ')$').exec(url.pathname);
  const creating=request.method==='POST'&&url.pathname==='/api/community';
  if(request.method!=='GET'&&!creating&&!(match&&['PATCH','DELETE'].includes(request.method)))return json({error:'Method not supported.'},405);
  try {
    if(request.method==='GET') {
      if(url.pathname!=='/api/community')return json({error:'Not found.'},404);
      const cursor=url.searchParams.get('cursor'),limit=30;let where='WHERE visible=1',params=[];
      if(cursor){const m=/^(\d{13}):([0-9a-f-]{36})$/.exec(cursor);if(!m)return json({error:'Invalid page.'},400);where='WHERE visible=1 AND (created_at < ? OR (created_at = ? AND id < ?))';params=[Number(m[1]),Number(m[1]),m[2]];}
      const queries=await db.batch([
        db.prepare('SELECT COUNT(*) AS wallets, COALESCE(SUM(MAX(0,CAST((? - first_at)/86400000 AS INTEGER))),0) AS days FROM community_contributions WHERE visible=1').bind(now),
        db.prepare('SELECT id,address,first_at,tx_hash,network,partial,message,topic,created_at,updated_at FROM community_contributions '+where+' ORDER BY created_at DESC,id DESC LIMIT ?').bind(...params,limit+1)
      ]);
      const rows=queries[1].results||[],more=rows.length>limit,last=rows[Math.min(rows.length,limit)-1],stats=queries[0].results?.[0]||{wallets:0,days:0};
      return json({schema:'abstract-community/v1',generatedAt:new Date(now).toISOString(),stats:{wallets:Number(stats.wallets),days:Number(stats.days),hours:Number(stats.days)*24},entries:rows.slice(0,limit).map(r=>publicContribution(r,now)),nextCursor:more?last.created_at+':'+last.id:null});
    }
    if(!sameOrigin(request))return json({error:'Submit from this site.'},403);
    const body=await readJson(request);
    if(!body||typeof body!=='object'||Array.isArray(body))return json({error:'Invalid contribution.'},400);
    if(match) {
      await rateLimit(request,db,now,'ledger-edit',30);
      if(typeof body.editKey!=='string'||!/^[0-9a-f]{64}$/.test(body.editKey))return json({error:'The private edit key is needed to manage this entry.'},403);
      const hash=await digest(body.editKey),existing=await db.prepare('SELECT id FROM community_contributions WHERE id=? AND edit_hash=?').bind(match[1],hash).first();
      if(!existing)return json({error:'This entry could not be accessed. Check your private edit key.'},403);
      if(request.method==='DELETE'){await db.prepare('DELETE FROM community_contributions WHERE id=? AND edit_hash=?').bind(match[1],hash).run();return json({removed:true});}
      if(typeof body.message!=='string'||body.message.length>2500||!Object.hasOwn(COMMUNITY_TOPICS,body.topic)||/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/.test(body.message))return json({error:'Choose a topic and keep your message within 2,500 characters.'},400);
      await db.prepare('UPDATE community_contributions SET message=?,topic=?,updated_at=? WHERE id=? AND edit_hash=?').bind(body.message.trim(),body.topic,now,match[1],hash).run();return json({updated:true});
    }
    if(body.consent!==true)return json({error:'Choose to share your wallet receipt before contributing.'},400);
    if(!validAddress(body.address)||typeof body.message!=='string'||body.message.length>2500||!Object.hasOwn(COMMUNITY_TOPICS,body.topic)||/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/.test(body.message))return json({error:'Use a valid wallet, choose a topic, and keep your message within 2,500 characters.'},400);
    const address=body.address.toLowerCase();
    if(body.editKey!==undefined&&(typeof body.editKey!=='string'||!/^[0-9a-f]{64}$/.test(body.editKey)))return json({error:'Invalid private edit key.'},400);
    const existing=await db.prepare('SELECT id,edit_hash,first_at FROM community_contributions WHERE address=?').bind(address).first();
    if(existing){if(body.editKey&&await digest(body.editKey)===existing.edit_hash)return json({id:existing.id,address,editKey:body.editKey,days:Math.max(0,Math.floor((now-existing.first_at)/DAY_MS)),alreadyAdded:true});return json({error:'This wallet is already in the total. Use its private edit key to update the message; it won’t count twice.',code:'already-added'},409);}
    const ip=request.headers.get('cf-connecting-ip')||request.headers.get('oai-authenticated-user-id')||'unknown',window=Math.floor(now/900000);
    const rateKey=await digest('community:'+window+':'+ip);
    const rate=await db.prepare('INSERT INTO community_limits (key,window,attempts) VALUES (?,?,1) ON CONFLICT(key) DO UPDATE SET attempts=attempts+1 RETURNING attempts').bind(rateKey,window).first();
    if(Number(rate?.attempts)>5)return json({error:'Please wait a little before adding another wallet.'},429);
    const receiptUrl=new URL('/api/lookup',url.origin);receiptUrl.search=new URLSearchParams({address,testnet:'1'});
    const verified=await handleLookup(new Request(receiptUrl),fetcher,now),receipt=await verified.json();
    if(!verified.ok||!receipt.earliest)return json({error:'We couldn’t verify a first transaction right now. Keep your message and try again shortly.'},422);
    const first=receipt.earliest,key=body.editKey||accessKey(),id=crypto.randomUUID();
    await db.prepare('DELETE FROM community_limits WHERE window < ?').bind(window-96).run();
    const insert=await db.prepare('INSERT INTO community_contributions (id,address,first_at,tx_hash,network,partial,message,topic,edit_hash,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(address) DO NOTHING').bind(id,address,Date.parse(first.timestamp),first.hash,first.network,receipt.partial?1:0,body.message.trim(),body.topic,await digest(key),now,now).run();
    if(!insert.meta?.changes){const raced=await db.prepare('SELECT id,edit_hash,first_at FROM community_contributions WHERE address=?').bind(address).first();if(body.editKey&&raced?.edit_hash===await digest(body.editKey))return json({id:raced.id,address,editKey:body.editKey,days:Math.max(0,Math.floor((now-raced.first_at)/DAY_MS)),alreadyAdded:true});return json({error:'This wallet has already been added.',code:'already-added'},409);}
    return json({id,address,editKey:key,days:Math.max(0,Math.floor((now-Date.parse(first.timestamp))/DAY_MS))},201);
  }catch(error){if(error.status)return json({error:error.message},error.status);console.warn('Community request failed');return json({error:'The community ledger couldn’t save or load right now. Please try again.'},503);}
}

